const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a large polygon approximating the Great Plains grasslands in the US.
  const greatPlains = ee.Geometry.Polygon([
    [
      [-104.05, 49.0],  // NW corner (ND)
      [-104.05, 29.0],  // SW corner (TX)
      [-94.0, 29.0],   // SE corner (TX/OK)
      [-94.0, 49.0]    // NE corner (ND/MN)
    ]
  ]);

  const year1 = 2003;
  const year2 = 2019;

  // Define crop codes from USDA NASS CDL documentation.
  const cornCode = 1;
  const soybeansCode = 5;
  const winterWheatCode = 24;
  const springWheatCode = 23;
  const durumWheatCode = 22;

  const cropCodes = [cornCode, soybeansCode, winterWheatCode, springWheatCode, durumWheatCode];

  // 2. Data Acquisition & Processing Function
  const getCropArea = function(year) {
    const cdl = ee.ImageCollection('USDA/NASS/CDL')
                  .filter(ee.Filter.date(year + '-01-01', year + '-12-31'))
                  .first();

    // Check if the image exists for the given year
    if (!cdl) {
        return null; // Return null to indicate no image found
    }
    const cropland = cdl.select('cropland');

    // Create a binary mask for pixels matching any of the crop codes.
    // Use `eq` for each code and `reduce(ee.Reducer.anyNonZero())` to combine them.
    const cropMask = ee.ImageCollection(
        cropCodes.map(code => cropland.eq(code))
    ).reduce(ee.Reducer.anyNonZero());

    // Calculate the area of the masked pixels.
    // The result of ee.Image.pixelArea() is in sq meters. We multiply by the mask.
    const areaImage = cropMask.multiply(ee.Image.pixelArea());

    const stats = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: greatPlains,
      scale: 3000, // Use a coarse scale for a large area to avoid timeout
      maxPixels: 1e12
    });
    // The result is in square meters, so divide by 1e6 to get square kilometers.
    return ee.Number(stats.get('cropland')).divide(1e6);
  };

  // 3. Calculation for both years
  const area2003_ee = getCropArea(year1);
  const area2019_ee = getCropArea(year2);

  // The CDL collection is complete for these years, so we don't expect a C1 error.
  // But as a good practice, check for nulls that might come from the function.
  if (area2003_ee === null || area2019_ee === null) {
      console.log(`Evidence: Image collection empty for one or both years.`);
      console.log('A');
      return;
  }

  const area2003 = area2003_ee.getInfo();
  const area2019 = area2019_ee.getInfo();

  // 4. Validation & Final Answer
  if (area2003 === null || area2019 === null) {
    console.log(`Evidence: Calculation failed. Area result was null.`);
    console.log('C3');
    return;
  }

  if (area2003 === 0 || area2019 === 0) {
    console.log(`Evidence: No valid pixels found for specified crops in one or both years.`);
    console.log('C2');
    return;
  }

  const percentageChange = ((area2019 - area2003) / area2003) * 100;

  console.log(`Evidence: Corn, Wheat, Soybean Area in Great Plains.`);
  console.log(`2003 Area (sq km): ${area2003.toLocaleString('en-US', {maximumFractionDigits: 0})}`);
  console.log(`2019 Area (sq km): ${area2019.toLocaleString('en-US', {maximumFractionDigits: 0})}`);
  console.log(`Change: ${percentageChange.toFixed(2)}%`);

  if (area2019 > area2003) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
